    /**
     * Tests getting all Risks.
     *
     * @return    Collection
     */
    public List<Risk> testGetAll() throws Throwable {
    LOGGER.info( "RiskTest:testGetAll() - Retrieving Collection of Risks:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Risk : " );
    List<Risk> collection  = null;

    try {
        // call the static get method on the RiskService
        collection = service.getAllRisk();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Risk currEntity  = null;
            Iterator<Risk> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRiskId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

